/**
 * Initiate a connection to the server or reuse the existing connection to
 * send the message. This occurs each time a message is sent.
 */
connect() {
  // First, clear the QUIT delay timer if it's running.
  if (this._quitTimer) {
    clearTimeout(this._quitTimer);
    this._quitTimer = null;
  }
  // A close still pending from an earlier QUIT must not close the socket we
  // are about to use.
  this._clearQuitCloseTimer();

  const isSocketOpen = this.socket?.readyState == "open";
  if (isSocketOpen && this._reuseConnection) {
    this.logger.debug("Reusing a connection");
    this.onidle();
  } else {
    // Socket is not open OR connection is not to be reused. If the connection
    // is still open, probably because QUIT has not yet caused the connection
    // to be closed, then immediately close the old connection before making
    // the new connection.
    if (isSocketOpen) {
      // Close the connection and skip calling _free() in _onClose to prevent
      // an immediate call to connect() if another message is awaiting being
      // sent.
      this.socket.onclose = this._onClose(false); // Don't call _free()
      this.close(true);
    }
    const hostname = this._server.hostname.toLowerCase();
    const port = this._server.port || (this.options.requireTLS ? 465 : 587);
    this.logger.debug(`Connecting to smtp://${hostname}:${port}`);
    this._secureTransport = this.options.requireTLS;
    this.socket = new TCPSocket(hostname, port, {
      binaryType: "arraybuffer",
      useSecureTransport: this._secureTransport,
    });

    this.socket.onerror = this._onError;
    this.socket.onopen = this._onOpen;

    // Reset these counters when a new connection is opened. When the number
    // of messages sent or the number of recipients for the messages reaches
    // their respective threshold, a new connection will be established.
    this._numMessages = 0;
    this._rcptCount = 0;
  }
  this._freed = false;
}

/**
 * Sends QUIT.
 * Ignore the response to QUIT (i.e., "221 <text>") since connection is done.
 * Also, don't do close() which confuses the server since, per RFC, the
 * connection close is be initiated by the server after receiving QUIT.
 * A server we can no longer reach never closes it, so fall back to closing
 * it here instead of leaving a dead socket for the next message to reuse.
 */
quit() {
  this._authenticating = false;
  this._currentAction = null; // Do no action after response to QUIT.
  this._sendCommand("QUIT");
  this._clearQuitCloseTimer();
  this._quitCloseTimer = setTimeout(() => {
    this._quitCloseTimer = null;
    this.logger.debug(
      `Server did not close after QUIT within ${
        QUIT_CLOSE_TIMEOUT_MS / 1000
      }s, tearing it down ourselves.`
    );
    this.close(true);
  }, QUIT_CLOSE_TIMEOUT_MS);
}
